-- Generated by `npm run db:schema` from a database built from supabase/migrations. Do not edit: change a migration.

create policy "participants read dispute evidence" on public.dispute_evidence
  as permissive
  for select
  to public
  using ((EXISTS ( SELECT 1
   FROM public.orders o
  WHERE o.id = dispute_evidence.order_id AND ((( SELECT auth.uid() AS uid)) = o.buyer_id OR (( SELECT auth.uid() AS uid)) = o.seller_id))));
